import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";

import { apiGet, apiPost, apiPut } from "../utils/api";

import InputField from "../components/InputField";
import InputSelect from "../components/InputSelect";
import FlashMessage from "../components/FlashMessage";

const InvoiceForm = () => {
    const navigate = useNavigate();
    const { id } = useParams();

    const [sellerListState, setSellerList] = useState([]);
    const [buyerListState, setBuyerList] = useState([]);
    const [sellerState, setSeller] = useState("");
    const [buyerState, setBuyer] = useState("");

    const [invoice, setInvoice] = useState({
        invoiceNumber: "",
        sellerID: sellerState,
        buyerID: buyerState,
        issued: new Date().toISOString().split("T")[0],
        dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
        product: "",
        price: "",
        vat: "21",
        note: "",
    });

    const [sentState, setSent] = useState(false);
    const [successState, setSuccess] = useState(false);
    const [errorState, setError] = useState(null);

    useEffect(() => {
        if (id) {
            apiGet("/api/persons/" + id)
                .then((data) => {
                    console.log("Fetched Invoice:", data);
                    setInvoice(data);
                    setSeller(data.sellerID);
                    setBuyer(data.buyerID);

                    if (data.sellerID) {
                        apiGet("/api/persons/" + data.sellerID)
                            .then((sellerData) => {
                                console.log("Fetched Seller:", sellerData);
                                setSeller(sellerData.id);
                            })
                            .catch((error) => console.error("Error fetching seller:", error));
                    }
                })
                .catch((error) => console.error("Error fetching invoice:", error));
        }
    }, [id]);

    useEffect(() => {
        apiGet("persons")
            .then((data) => {
                setSellerList(data);
                setBuyerList(data);
            })
            .catch((error) => console.error("Error fetching persons:", error));
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        console.log(`Changed field: ${name}, New value: ${value}`);

        if (name === "seller") {
            setSeller(value);
            setInvoice((prevInvoice) => ({ ...prevInvoice, sellerID: value }));
        } else if (name === "buyer") {
            setBuyer(value);
            setInvoice((prevInvoice) => ({ ...prevInvoice, buyerID: value }));
        } else {
            setInvoice((prevInvoice) => ({ ...prevInvoice, [name]: value }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!invoice.sellerID) {
            setError("Prosím, vyberte prodávajícího.");
            return;
        }

        (id ? apiPut("/api/invoices/" + id, invoice) : apiPost("/api/invoices", invoice))
            .then(() => {
                setSent(true);
                setSuccess(true);
                navigate("/invoices");
            })
            .catch((error) => {
                console.log(error.message);
                setError(error.message);
                setSent(true);
                setSuccess(false);
            });
    };

    return (
        <div>
            <h1>{id ? "Upravit" : "Vytvořit"} fakturu</h1>
            <hr />
            {errorState && <div className="alert alert-danger">{errorState}</div>}
            {sentState && (
                <FlashMessage
                    theme={successState ? "success" : ""}
                    text={successState ? "Uložení faktury proběhlo úspěšně." : ""}
                />
            )}
            <form onSubmit={handleSubmit}>
                <InputField
                    required
                    type="text"
                    name="invoiceNumber"
                    min="3"
                    label="Číslo faktury"
                    prompt="Zadejte číslo faktury"
                    value={invoice.invoiceNumber}
                    handleChange={handleChange}
                />

                <InputSelect
                    name="seller"
                    items={sellerListState}
                    label="Prodávající"
                    prompt="Vyberte prodávajícího"
                    value={sellerState}
                    handleChange={handleChange}
                />

                <InputSelect
                    name="buyer"
                    items={buyerListState}
                    label="Kupující"
                    prompt="Vyberte kupujícího"
                    value={buyerState}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="date"
                    name="issued"
                    label="Datum vydání faktury"
                    value={invoice.issued}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="date"
                    name="dueDate"
                    label="Datum splatnosti faktury"
                    value={invoice.dueDate}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="product"
                    min="3"
                    label="Název produktu"
                    prompt="Zadejte název produktu"
                    value={invoice.product}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="note"
                    min="3"
                    label="Popis"
                    value={invoice.note}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="vat"
                    min="3"
                    label="Daň"
                    value={invoice.vat}
                    handleChange={handleChange}
                />

                <InputField
                    required
                    type="text"
                    name="price"
                    min="3"
                    label="Cena"
                    value={invoice.price}
                    handleChange={handleChange}
                />

                <input type="submit" className="btn btn-primary" value="Uložit" />
            </form>
        </div>
    );
};

export default InvoiceForm;
